    "signature": "tools.linear.get_attachment({
  /** Issue attachment ID from get_issue's attachments array (attachments[].id) */
  id: string,
  /**
   * Omit or use content to fetch a Linear-hosted file. Use url for attachment metadata without fetching the file; also supports external links
   */
  format?: "content" | "url",
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.get_template",
    "description": "Retrieve a Linear template by ID or name: the content it pre-fills, the ids it applies, its sub-issues, and its form fields. Pass the template to save_issue or save_project to apply it. References come back as ids, so read a name with the matching tool when you need one. A form template collects its answers through a form, so applying one here creates an issue with the form unanswered.",
    "signature": "tools.linear.get_template({
  /** Template ID or name */
  id: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.get_triage_responsibility",
    "description": "Retrieve who is responsible for a team's triage: the person on triage now, what happens when an issue enters triage, and the upcoming shifts of the team's triage rotation. Pass `user` to get only that person's shifts, for example to find when their next triage duty starts, even when it is weeks away.",
    "signature": "tools.linear.get_triage_responsibility({
  /** Team name or ID */
  team: string,
  /** Only return shifts of this user: User ID, name, email, or "me" */
  user?: string,
  /** Max upcoming shifts to return (default 10, max 50). @default 10 @integer @minimum 1 @maximum 50 */
  limit?: number,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.create_issue_label",
    "description": "Create a new Linear issue label. Deprecated: use `save_issue_label`, which can also update labels.",
    "signature": "tools.linear.create_issue_label({
  /** Label name */
  name: string,
  /** Label description */
  description?: string,
  /** Hex color code */
  color?: string,
  /** Team UUID (omit for workspace label) */
  teamId?: string,
  /** Parent label group name or ID */
  parent?: string,
  /** Whether the label is a group. @default false */
  isGroup?: boolean,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.get_notifications",
    "description": "Get a page of notifications from the authenticated user's Linear inbox.",
    "signature": "tools.linear.get_notifications({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Only return unread notifications. @default false */
  unreadOnly?: boolean,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.list_issue_labels",
    "description": "List available issue labels in a Linear workspace or team. A retired label carries `retiredAt` and cannot be applied to new issues.",
    "signature": "tools.linear.list_issue_labels({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Timestamp to sort results by: creation time or last update time. @default "updatedAt" */
  orderBy?: "createdAt" | "updatedAt",
  /** Filter by name */
  name?: string,
  /** Team name or ID */
  team?: string,
  /** Include archived items. @default false */
  includeArchived?: boolean,
  /**
   * Include label groups in the results, marked with `isGroup`. A group cannot be applied directly; retiring or restoring one cascades to its child labels
   * @default false
   */
  includeGroups?: boolean,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.list_issue_statuses",
    "description": "List available issue statuses in a Linear team",
    "signature": "tools.linear.list_issue_statuses({
  /** Team name or ID */
  team: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.restore_issue_label",
    "description": "Restore a retired Linear issue label, making it available for use on issues again. Restoring a label group also restores every child label, including any that were retired separately.",
    "signature": "tools.linear.restore_issue_label({
  /** Label or label group ID */
  id: string,
}): Promise<unknown>"
  }
]

