    assert [_] = WorkshopCalendarHTTP.mutations(server)

    assert {:ok, _} =
             Workshops.update_workshop(workshop.id, %{title: "Updated", location: "New hall"})

    assert :ok = sync(workshop.id)
    [updated] = Map.values(WorkshopCalendarHTTP.events(server))
    assert updated["id"] == event["id"]
    assert updated["summary"] == "[Planned] Updated"
    assert updated["location"] == "New hall"

    Agent.update(server, fn state ->
      drifted =
        Map.merge(updated, %{
          "summary" => "Google edit",
          "attendees" => [%{"email" => "private@example.com"}]
        })

      %{state | events: %{event["id"] => drifted}}
    end)

    assert :ok = sync(workshop.id)
    [repaired] = Map.values(WorkshopCalendarHTTP.events(server))
    assert repaired["summary"] == "[Planned] Updated"
    assert repaired["attendees"] == []
    assert Enum.all?(WorkshopCalendarHTTP.mutations(server), &(&1.query == "sendUpdates=none"))
  end

  # ALE-440: a manually entered destination supplies Calendar's native
  # location; enriching one is an ordinary meaningful change for the shared
  # protocol, and an unchanged destination stays silent.
  test "a manual destination supplies the native location and its enrichment updates the same committee event silently to attendees" do
    server = google_surface!()

    %{principal_id: principal_id} = WorkshopFixtures.member_fixture()

    {:ok, workshop} =
      Workshops.create_workshop(
        %{
          title: "Longsword",
          description: "PRIVATE notes, medical and payment details",
          location: "Club hall",
          destination_name: "National Basketball Arena",
          destination_address: "Tymon Park, Dublin 6w",
          start_date: ~U[2027-03-28 09:00:00Z],
          end_date: ~U[2027-03-28 11:00:00Z],
          max_capacity: 20,
          price_member: 1000.0,
          price_non_member: 2000.0
        },
        principal_id
      )

    assert :ok = sync(workshop.id)
    [event] = Map.values(WorkshopCalendarHTTP.events(server))
    assert event["location"] == "National Basketball Arena, Tymon Park, Dublin 6w"

    # Destination enrichment: same event identity, no duplicate, committee
    # mutations stay non-notifying.
    assert {:ok, _} =
             Workshops.update_workshop(workshop.id, %{
               destination_name: "National Basketball Arena",
               destination_address: "Tymon Road, Dublin 6w",
               directions_url: "https://maps.app.goo.gl/AbCdEf"
             })

    assert :ok = sync(workshop.id)
    [updated] = Map.values(WorkshopCalendarHTTP.events(server))
    assert updated["id"] == event["id"]
    assert updated["location"] == "National Basketball Arena, Tymon Road, Dublin 6w"
    assert map_size(WorkshopCalendarHTTP.events(server)) == 1

    mutations = WorkshopCalendarHTTP.mutations(server)
    assert Enum.all?(mutations, &(&1.query == "sendUpdates=none"))
    # The directions link never reaches Calendar content.
    refute Jason.encode!(updated) =~ "maps.app.goo.gl"

    # Unchanged reconciliation after enrichment stays silent.
    assert :ok = sync(workshop.id)
    assert mutations == WorkshopCalendarHTTP.mutations(server)
  end

  test "a label-only Workshop keeps its label as the native location" do
    server = google_surface!()
    workshop = create_workshop!()

    assert :ok = sync(workshop.id)
    [event] = Map.values(WorkshopCalendarHTTP.events(server))
    assert event["location"] == "Club hall"
  end

  test "cancellation keeps committee history at its scheduled time even when work arrives after end" do
    server = google_surface!()
    workshop = create_workshop!()
    {:ok, _} = Workshops.publish_workshop(workshop.id)
    assert :ok = sync(workshop.id)
    [event] = Map.values(WorkshopCalendarHTTP.events(server))
    {:ok, _} = Workshops.cancel_workshop(workshop.id)

    assert :ok = sync_at(workshop.id, ~U[2027-03-29 12:00:00Z])
    [cancelled] = Map.values(WorkshopCalendarHTTP.events(server))
    assert cancelled["summary"] == "[Cancelled] Longsword"
    assert cancelled["status"] == "confirmed"
    assert cancelled["start"] == event["start"]
    assert cancelled["end"] == event["end"]
    assert cancelled["location"] == event["location"]
  end

  test "deletion work survives the source, inactive configuration, and event end; repairs do not resurrect it" do
    server = google_surface!()
    workshop = create_workshop!()

    assert {:ok, _} =
             Workshops.create_external_checkout_session(
               workshop.id,
               attempt,
               "http://localhost:5173/return?session_id={CHECKOUT_SESSION_ID}"
             )

    assert :ok = sync(workshop.id)
    assert WorkshopCalendarHTTP.mutations(server) == []

    assert {:ok, registration} =
             Workshops.complete_external_registration(workshop.id, "cs_external")

    assert {:ok, %{id: id}} = Workshops.complete_external_registration(workshop.id, "cs_external")
    assert id == registration.id
    args = %{"source_kind" => "workshop", "source_id" => workshop.id, "audience" => "participant"}
    assert :ok = perform_job(SyncWorker, args)
    count = length(WorkshopCalendarHTTP.mutations(server))
    assert :ok = perform_job(SyncWorker, args)
    assert length(WorkshopCalendarHTTP.mutations(server)) == count
    assert [%{"email" => "guest@example.com"}] = event(server)["attendees"]
  end

  test "a destination gives both audiences the same native location while the participant event keeps its privacy",
       %{server: server} do
    workshop =
      WorkshopFixtures.workshop_fixture(
        status: "published",
        is_public: true,
        price_member: 1800.0,
        price_non_member: 2400.0,
        destination_name: "National Basketball Arena",
        destination_address: "Tymon Park, Dublin 6w",
        directions_url: "https://maps.app.goo.gl/AbCdEf",
        start_date: ~U[2027-03-28 09:00:00Z],
        end_date: ~U[2027-03-28 11:00:00Z]
      )

    member = WorkshopFixtures.member_fixture()
    registration = confirm!(workshop, member)

    # The participant event is created with the recognizable destination as
    # its native location, and repeated synchronization is a no-op.
    assert :ok = sync(workshop.id)
    participant = event(server)
    assert participant["location"] == "National Basketball Arena, Tymon Park, Dublin 6w"
    assert participant["attendees"] == [%{"email" => registration.email}]
    refute Map.has_key?(participant, "description")
    # The directions link and every other destination extra stay off Google.
    refute Jason.encode!(participant) =~ "maps.app.goo.gl"

    mutations = WorkshopCalendarHTTP.mutations(server)
    assert :ok = sync(workshop.id)
    assert WorkshopCalendarHTTP.mutations(server) == mutations
    assert map_size(WorkshopCalendarHTTP.events(server)) == 1

    # The committee audience shows the same destination, not conflicting
    # location information.
    assert :ok = WorkshopCalendar.sync(:workshop, workshop.id, clock: fn -> @now end)

    [committee] =
      WorkshopCalendarHTTP.events(server)
      |> Map.values()
      |> Enum.reject(&Map.has_key?(&1, "attendees"))

    assert committee["id"] != participant["id"]
    assert committee["location"] == participant["location"]
  end

  test "pending checkout and compensating payments never receive an invitation", %{server: server} do
    workshop = workshop!()
    member = WorkshopFixtures.member_fixture()

    intent =
      StripeStub.member_payment_intent("pi_pending", workshop.id, member.principal_id, %{
        "status" => "processing"
      })

    StripeHTTPStub.stub("GET", "/v1/payment_intents/pi_pending", &StripeHTTPStub.json(&1, intent))

    assert {:error, :payment_not_completed} =
             Workshops.complete_member_registration(
               workshop.id,
               member.principal_id,
               "pi_pending"
             )

    assert :ok = sync(workshop.id)
    assert WorkshopCalendarHTTP.mutations(server) == []
    assert {:ok, _} = Workshops.cancel_workshop(workshop.id)
        conn
